module main

fn rectangles(strings []string) int {
	is_corner := fn [strings] (row int, col int) bool {
		return strings[row][col] == u8(`+`)
	}

	is_horizontal := fn [strings] (row int, col int) bool {
		return strings[row][col] == u8(`-`) || strings[row][col] == u8(`+`)
	}

	is_vertical := fn [strings] (row int, col int) bool {
		return strings[row][col] == u8(`|`) || strings[row][col] == u8(`+`)
	}

	mut result := 0
	for top in 0 .. (strings.len) {
		for left in 0 .. (strings[0].len) {
			if !is_corner(top, left) {
				continue
			}

			for bottom in (top + 1) .. (strings.len) {
				if !is_vertical(bottom, left) {
					break
				}
				if !is_corner(bottom, left) {
					continue
				}

				for right in (left + 1) .. (strings[0].len) {
					if !is_horizontal(top, right) || !is_horizontal(bottom, right) {
						break
					}
					if !is_corner(top, right) || !is_corner(bottom, right) {
						continue
					}

					mut valid := true
					for row in (top + 1) .. bottom {
						if !is_vertical(row, right) {
							valid = false
							break
						}
					}
					if valid {
						result++
					}
				}
			}
		}
	}
	return result
}

test_code:
module main

fn test_no_rows() {
	strings := []string{}
	assert rectangles(strings) == 0
}

fn test_no_columns() {
	strings := [
		'',
	]
	assert rectangles(strings) == 0
}

fn test_no_rectangles() {
	strings := [
		' ',
	]
	assert rectangles(strings) == 0
}

fn test_one_rectangle() {
	strings := [
		'+-+',
		'| |',
		'+-+',
	]
	assert rectangles(strings) == 1
}

fn test_two_rectangles_without_shared_parts() {
	strings := [
		'  +-+',
		'  | |',
		'+-+-+',
		'| |  ',
		'+-+  ',
	]
	assert rectangles(strings) == 2
}

fn test_five_rectangles_with_shared_parts() {
	strings := [
		'  +-+',
		'  | |',
		'+-+-+',
		'| | |',
		'+-+-+',
	]
	assert rectangles(strings) == 5
}

fn test_rectangle_of_height_1_is_counted() {
	strings := [
		'+--+',
		'+--+',
	]
	assert rectangles(strings) == 1
}

fn test_rectangle_of_width_1_is_counted() {
	strings := [
		'++',
		'||',
		'++',
	]
	assert rectangles(strings) == 1
}

fn test_1x1_square_is_counted() {
	strings := [
		'++',
		'++',
	]
	assert rectangles(strings) == 1
}

fn test_only_complete_rectangles_are_counted() {
	strings := [
		'  +-+',
		'    |',
		'+-+-+',
		'| | -',
		'+-+-+',
	]
	assert rectangles(strings) == 1
}

fn test_rectangles_can_be_of_different_sizes() {
	strings := [
		'+------+----+',
		'|      |    |',
		'+---+--+    |',
		'|   |       |',
		'+---+-------+',
	]
	assert rectangles(strings) == 3
}

fn test_corner_is_required_for_a_rectangle_to_be_complete() {
	strings := [
		'+------+----+',
		'|      |    |',
		'+------+    |',
		'|   |       |',
		'+---+-------+',
	]
	assert rectangles(strings) == 2
}

fn test_large_input_with_many_rectangles() {
	strings := [
		'+---+--+----+',
		'|   +--+----+',
		'+---+--+    |',
		'|   +--+----+',
		'+---+--+--+-+',
		'+---+--+--+-+',
		'+------+  | |',
		'          +-+',
	]
	assert rectangles(strings) == 60
}

fn test_rectangles_must_have_four_sides() {
	strings := [
		'+-+ +-+',
		'| | | |',
		'+-+-+-+',
		'  | |  ',
		'+-+-+-+',
		'| | | |',
		'+-+ +-+',
	]
	assert rectangles(strings) == 5
}
